import * as React from "react"
import { addPropertyControls, ControlType, RenderTarget } from "framer"

/**
 * NimbusSequencePlayer — scroll-driven image sequence, tuned for phones.
 *
 * Same mapping as the ImageSequence marketplace component (Trigger "Top":
 * frame = (scrollY - top - delay) / sectionHeight * count), but:
 *  - one <canvas>, drawn at most once per animation frame and only when the
 *    frame index changes (no React re-render of every frame on scroll);
 *  - frames are fetched up front (encoded, small) and decoded ahead of the
 *    scroll direction in a sliding window, so the next frames are ready
 *    before they are shown, without holding every decoded frame in memory.
 *
 * @framerSupportedLayoutWidth any
 * @framerSupportedLayoutHeight any
 */
type Props = {
    frames: string
    sectionHeight: number
    rangeVh?: number
    startDelay: number
    decodeAhead: number
    smoothing: number
    style?: React.CSSProperties
}

export default function NimbusSequencePlayer(props: Props) {
    const { frames = "", sectionHeight = 1688, rangeVh = 0, startDelay = 0, decodeAhead = 12, smoothing = 0.12, style } = props
    const urls = React.useMemo(
        () =>
            String(frames || "")
                .split(/[\s,]+/)
                .map((s) => s.trim())
                // accept absolute and site-relative URLs (self-hosted exports rewrite to /_remote/...)
                .filter((s) => /^(https?:)?\/\//.test(s) || s.startsWith("/") || s.startsWith("./"))
                .map((s) => {
                    try {
                        return typeof window === "undefined" ? s : new URL(s, window.location.href).href
                    } catch {
                        return s
                    }
                }),
        [frames]
    )
    const isCanvas = RenderTarget.current() === RenderTarget.canvas
    const wrapRef = React.useRef<HTMLDivElement | null>(null)
    const canvasRef = React.useRef<HTMLCanvasElement | null>(null)

    React.useEffect(() => {
        if (isCanvas || !urls.length) return
        const wrap = wrapRef.current
        const canvas = canvasRef.current
        if (!wrap || !canvas) return
        const ctx = canvas.getContext("2d", { alpha: true })
        if (!ctx) return

        let disposed = false
        const count = urls.length
        // Encoded bytes (small) for every frame, fetched a few at a time in order;
        // decoded bitmaps only near the playhead. Decoding from a Blob runs off the
        // main thread (decoding from an <img> blocks scrolling on Chrome/Android).
        const blobs: (Promise<Blob> | null)[] = new Array(count).fill(null)
        const ctrl = typeof AbortController !== "undefined" ? new AbortController() : null
        const getBlob = (i: number) => {
            if (!blobs[i]) {
                blobs[i] = fetch(urls[i], { signal: ctrl?.signal, cache: "force-cache" }).then((r) => {
                    if (!r.ok) throw new Error(String(r.status))
                    return r.blob()
                })
                blobs[i]!.catch(() => {
                    blobs[i] = null
                })
            }
            return blobs[i]!
        }
        // Download progress for the page loader (Asset Loading → Wait for Sequence).
        // Progress = all downloads + the first frames decoded and ready to draw,
        // so the first scroll after the loader never waits on a decode.
        let loaded = 0
        let warmTarget = 0 // set once the decode window is known
        const warmed = new Set<number>()
        const report = () => {
            const detail = { loaded: loaded + Math.min(warmed.size, warmTarget), total: count + warmTarget }
            ;(window as any).__nimbusSequenceProgress = detail
            window.dispatchEvent(new CustomEvent("botanika:sequence-progress", { detail }))
        }
        report()
        ;(async () => {
            let next = 0
            const worker = async () => {
                while (!disposed && next < count) {
                    const i = next++
                    try {
                        await getBlob(i)
                    } catch {}
                    if (disposed) return
                    loaded++ // failed frames count too, so the loader never hangs
                    report()
                }
            }
            await Promise.all([worker(), worker(), worker(), worker()])
        })()
        // WebKit (every iPhone browser) decodes createImageBitmap(blob) on the main
        // thread; HTMLImageElement.decode() is the async path there. It also has
        // less memory headroom on older iPhones, so keep a tighter window.
        const ua = typeof navigator !== "undefined" ? navigator.userAgent : ""
        const isWebKit =
            (window as any).__nspForceImg === true ||
            (/AppleWebKit/.test(ua) && !/Chrome|Chromium|Android|Edg\//.test(ua)) ||
            /iPhone|iPad|iPod/.test(ua) ||
            (navigator.platform === "MacIntel" && (navigator as any).maxTouchPoints > 1)
        const MAX_DECODING = isWebKit ? 2 : 3
        const ahead = isWebKit ? Math.min(decodeAhead, 12) : decodeAhead
        const keep = isWebKit ? ahead + Math.ceil(ahead / 3) + 2 : ahead * 2 + 4
        warmTarget = Math.min(count, ahead + 1)
        // Sparse "anchor" frames stay decoded for the whole session, so a fast flick
        // (faster than the device can decode) still shows the lid moving instead of
        // freezing on the last frame. ~13 bitmaps on a 201-frame sequence.
        const ANCHOR = Math.max(4, Math.round(count / 12))
        const isAnchor = (i: number) => i % ANCHOR === 0 || i === count - 1
        report()
        const objectUrls: string[] = []

        // Decode in Web Workers: the bitmap is built off the main thread in every
        // engine (incl. WebKit) and transferred back ready to draw.
        type Job = { done: (b: ImageBitmap | null) => void; fallback: () => void }
        const workerJobs = new Map<number, Job>()
        const workers: Worker[] = []
        let workerUrl = ""
        let workersOk = typeof Worker !== "undefined" && typeof createImageBitmap === "function"
        if (workersOk) {
            try {
                const src =
                    "self.onmessage=async(e)=>{const{i,blob}=e.data;try{const bm=await createImageBitmap(blob);self.postMessage({i,bm},[bm])}catch(err){self.postMessage({i,err:String(err)})}}"
                workerUrl = URL.createObjectURL(new Blob([src], { type: "text/javascript" }))
                for (let k = 0; k < 2; k++) {
                    const w = new Worker(workerUrl)
                    w.onmessage = (e: MessageEvent) => {
                        const { i, bm, err } = e.data || {}
                        const job = workerJobs.get(i)
                        workerJobs.delete(i)
                        if (!job) return bm?.close?.()
                        if (bm) job.done(bm)
                        else {
                            workersOk = false // e.g. no createImageBitmap in workers: use the main-thread path
                            job.fallback()
                        }
                    }
                    w.onerror = () => {
                        workersOk = false
                        const jobs = [...workerJobs.values()]
                        workerJobs.clear()
                        jobs.forEach((j) => j.fallback())
                    }
                    workers.push(w)
                }
            } catch {
                workersOk = false
            }
        }
        let rr = 0
        const nextWorker = () => (workersOk && workers.length ? workers[rr++ % workers.length] : null)
        const stats = { n: 0, sum: 0, max: 0, viaImg: 0 }
        const bitmaps = new Map<number, ImageBitmap | HTMLImageElement>()
        const pending = new Set<number>()
        // The component may be fixed (top 0) or in flow; measure its document top once.
        const rect0 = wrap.getBoundingClientRect()
        const fixed = getComputedStyle(wrap).position === "fixed" || wrap.closest("[style*='position: fixed']")
        // Inside a sticky pin, measure the pin's container: the sticky box itself
        // reports top 0 whenever the page is reloaded mid-section.
        let stickyHost: Element | null = null
        let stickyEl: Element | null = null
        for (let n: Element | null = wrap; n && n !== document.body; n = n.parentElement) {
            if (getComputedStyle(n).position === "sticky") {
                stickyEl = n
                stickyHost = n.parentElement
                break
            }
        }
        // Scroll distance of the animation. Inside a sticky pin it is the pin's
        // travel (container height - sticky height), so it follows whatever the
        // spacer is set to on the canvas (e.g. 100vh). Otherwise: Section Height.
        let rangePx = Math.max(1, sectionHeight)
        const measureRange = () => {
            if (rangeVh > 0) {
                rangePx = Math.max(1, (window.innerHeight * rangeVh) / 100 - startDelay)
                return
            }
            if (stickyHost && stickyEl) {
                const r =
                    stickyHost.getBoundingClientRect().height - stickyEl.getBoundingClientRect().height - startDelay
                if (r > 50) {
                    rangePx = r
                    return
                }
            }
            rangePx = Math.max(1, sectionHeight)
        }
        measureRange()
        const ro =
            stickyHost && typeof ResizeObserver !== "undefined"
                ? new ResizeObserver(() => {
                      measureRange()
                      schedule()
                  })
                : null
        if (ro && stickyHost) ro.observe(stickyHost)
        const top = fixed
            ? 0
            : stickyHost
              ? stickyHost.getBoundingClientRect().top + window.scrollY
              : rect0.top + window.scrollY

        // Scroll position as a fractional frame (smoothed below).
        const targetFor = () => {
            const y = (window.scrollY || 0) - top - startDelay
            return Math.max(0, Math.min(count - 1, (y / rangePx) * count))
        }
        let cur = targetFor()
        let lastT = 0
        const indexFor = () => Math.max(0, Math.min(count - 1, Math.round(cur)))

        const decode = (i: number) => {
            if (i < 0 || i >= count || bitmaps.has(i) || pending.has(i) || disposed) return
            if (pending.size >= MAX_DECODING) return // retried from the next frame()
            pending.add(i)
            const t0 = performance.now()
            const done = (b: ImageBitmap | HTMLImageElement | null) => {
                pending.delete(i)
                if (b) {
                    stats.n++
                    const ms = performance.now() - t0
                    stats.sum += ms
                    stats.max = Math.max(stats.max, ms)
                }
                if (disposed) {
                    ;(b as any)?.close?.()
                    return
                }
                if (b) bitmaps.set(i, b)
                if (i >= warmStart && i < warmStart + warmTarget && !warmed.has(i)) {
                    warmed.add(i) // failed decodes count too, so the loader never hangs
                    report()
                }
                schedule() // draw if wanted, and start the next queued decode
            }
            const viaImg = (src: string) => {
                stats.viaImg++
                const im = new Image()
                im.crossOrigin = "anonymous"
                im.decoding = "async"
                im.src = src
                im.decode().then(() => done(im), () => done(null))
            }
            const onMain = (blob: Blob) => {
                if (!isWebKit && typeof createImageBitmap === "function") {
                    createImageBitmap(blob).then(done, () => viaImg(urls[i]))
                } else {
                    if (!objectUrls[i]) objectUrls[i] = URL.createObjectURL(blob)
                    viaImg(objectUrls[i])
                }
            }
            getBlob(i).then(
                (blob) => {
                    const w = nextWorker()
                    if (!w) return onMain(blob)
                    workerJobs.set(i, { done, fallback: () => onMain(blob) })
                    w.postMessage({ i, blob })
                },
                () => viaImg(urls[i])
            )
        }

        let want = indexFor()
        const warmStart = Math.max(0, Math.min(want, count - warmTarget)) // frames the loader waits for
        let raf = 0
        const schedule = () => {
            if (!raf) raf = requestAnimationFrame(frame)
        }
        let drawn = -1
        let lastIndex = want
        let dir = 1
        let cw = 0
        let ch = 0

        const evict = () => {
            for (const [k, b] of bitmaps) {
                if (Math.abs(k - want) > keep && !isAnchor(k)) {
                    ;(b as any).close?.()
                    bitmaps.delete(k)
                }
            }
        }
        const warm = (target: number) => {
            const goal = Math.round(target)
            if (Math.abs(goal - want) > ahead) {
                // Flick: the playhead is far behind the scroll. Decode where it is
                // heading (exact frame, then the anchor next to it) before neighbours.
                decode(goal)
                decode(Math.round(goal / ANCHOR) * ANCHOR)
            }
            decode(want)
            for (let d = 1; d <= ahead; d++) {
                decode(want + d * dir) // ahead first
            }
            for (let d = 1; d <= Math.ceil(ahead / 3); d++) decode(want - d * dir)
            // idle slots: fill in the anchors (nearest first)
            if (pending.size < MAX_DECODING) {
                for (let d = 0; d <= count; d += ANCHOR) {
                    const a = Math.round(want / ANCHOR) * ANCHOR
                    for (const k of [a + d, a - d]) if (k >= 0 && k < count && !bitmaps.has(k)) decode(k)
                    if (pending.size >= MAX_DECODING) break
                }
                if (!bitmaps.has(count - 1)) decode(count - 1)
            }
            evict()
        }

        const resize = () => {
            const r = wrap.getBoundingClientRect()
            const dpr = Math.min(window.devicePixelRatio || 1, 2)
            const w = Math.max(1, Math.round(r.width * dpr))
            const h = Math.max(1, Math.round(r.height * dpr))
            if (w !== cw || h !== ch) {
                cw = w
                ch = h
                canvas.width = w
                canvas.height = h
                drawn = -1
            }
        }

        // Closest decoded frame anywhere (the map holds ~30 entries at most).
        const nearestReady = (i: number) => {
            if (bitmaps.has(i)) return i
            let best = -1
            let bestD = Infinity
            for (const k of bitmaps.keys()) {
                // tie: prefer the frame behind the playhead (never show "the future")
                const d = Math.abs(k - i) + ((k - i) * dir > 0 ? 0.5 : 0)
                if (d < bestD) {
                    bestD = d
                    best = k
                }
            }
            return best
        }

        const frame = (now: number) => {
            raf = 0
            if (disposed) return
            // Ease the playhead toward the scroll position (frame-rate independent),
            // so touch flicks and jumpy scroll still play every frame smoothly.
            const target = targetFor()
            const dt = lastT ? Math.min(0.1, (now - lastT) / 1000) : 1 / 60
            lastT = now
            if (smoothing > 0) {
                cur += (target - cur) * (1 - Math.exp(-dt / smoothing))
                if (Math.abs(target - cur) < 0.02) cur = target
            } else cur = target
            if (cur !== target) schedule()
            else lastT = 0
            want = indexFor()
            if (want !== lastIndex) {
                dir = want > lastIndex ? 1 : -1
                lastIndex = want
            }
            warm(target)
            resize()
            const i = nearestReady(want)
            if (i < 0 || i === drawn) return
            const img = bitmaps.get(i) as any
            const iw = img.width || img.naturalWidth
            const ih = img.height || img.naturalHeight
            // object-fit: cover, centred (same framing as the captured viewport)
            const s = Math.max(cw / iw, ch / ih)
            const dw = iw * s
            const dh = ih * s
            ctx.clearRect(0, 0, cw, ch)
            ctx.drawImage(img, (cw - dw) / 2, (ch - dh) / 2, dw, dh)
            drawn = i
        }

        // Past the lid section the (fixed) canvas sits under the rest of the page.
        // When the page above fully covers it, take it out of rendering so Safari
        // does not keep a composited layer under everything (memory + late paint).
        let hidden = false
        const canvasDisplay = canvas.style.display
        let coverTimer = 0
        const isOpaque = (el: Element) => {
            const cs = getComputedStyle(el)
            if (cs.backgroundImage && cs.backgroundImage !== "none") return true
            const m = cs.backgroundColor.match(/rgba?\(([^)]+)\)/)
            if (!m) return false
            const parts = m[1].split(",").map((s) => parseFloat(s))
            return parts.length < 4 || parts[3] >= 0.99
        }
        const coveredAt = (x: number, y: number) => {
            const els = document.elementsFromPoint(x, y)
            for (const el of els) {
                if (el === canvas || el === wrap || el.contains(wrap)) return false // reached the player first
                if (isOpaque(el) && el !== document.body && el !== document.documentElement) return true
            }
            return false
        }
        const checkCover = () => {
            coverTimer = 0
            if (disposed) return
            const past = (window.scrollY || 0) - top - startDelay > rangePx + 40
            let hide = false
            if (past) {
                const vw = window.innerWidth
                const vh = window.innerHeight
                // The player layer is pointer-events:none, which hit-testing skips;
                // make our wrapper hit-testable just for this synchronous check.
                const prevPE = wrap.style.pointerEvents
                wrap.style.pointerEvents = "auto"
                try {
                    hide = coveredAt(vw / 2, vh * 0.15) && coveredAt(vw / 2, vh * 0.5) && coveredAt(vw / 2, vh * 0.85)
                } finally {
                    wrap.style.pointerEvents = prevPE
                }
            }
            if (hide !== hidden) {
                hidden = hide
                canvas.style.display = hide ? "none" : canvasDisplay
                if (!hide) {
                    drawn = -1
                    schedule()
                }
            }
        }
        const onScroll = () => {
            schedule()
            if (!coverTimer) coverTimer = window.setTimeout(checkCover, 120)
        }
        window.addEventListener("scroll", onScroll, { passive: true })
        const onResize = () => {
            measureRange()
            schedule()
        }
        window.addEventListener("resize", onResize)
        schedule()
        checkCover()

        // On-device diagnostics: add ?nspdebug to the page URL.
        let dbgEl: HTMLDivElement | null = null
        let dbgTimer = 0
        let dbgRaf = 0
        if (/nspdebug/.test(window.location.search)) {
            dbgEl = document.createElement("div")
            dbgEl.style.cssText =
                "position:fixed;left:8px;top:80px;z-index:2147483646;background:rgba(0,0,0,.8);color:#0f0;font:11px/1.35 monospace;padding:6px 8px;border-radius:6px;pointer-events:none;white-space:pre"
            document.body.appendChild(dbgEl)
            let frames = 0
            let worst = 0
            let last = performance.now()
            const tick = (t: number) => {
                frames++
                worst = Math.max(worst, t - last)
                last = t
                dbgRaf = requestAnimationFrame(tick)
            }
            dbgRaf = requestAnimationFrame(tick)
            let prev = performance.now()
            dbgTimer = window.setInterval(() => {
                const now = performance.now()
                const fps = Math.round((frames * 1000) / (now - prev))
                frames = 0
                prev = now
                const p = (window as any).__nimbusSequenceProgress || {}
                dbgEl!.textContent =
                    `mode ${workersOk ? "worker" : "main"}${isWebKit ? " webkit" : ""}  img ${stats.viaImg}\n` +
                    `decode avg ${stats.n ? Math.round(stats.sum / stats.n) : 0}ms max ${Math.round(stats.max)}ms n ${stats.n}\n` +
                    `frame ${drawn}/${count} want ${want} target ${Math.round(targetFor())}\n` +
                    `cached ${bitmaps.size} pending ${pending.size}  load ${p.loaded ?? "?"}/${p.total ?? "?"}\n` +
                    `fps ${fps} worst ${Math.round(worst)}ms  top ${Math.round(top)} y ${Math.round(window.scrollY)}  ${hidden ? "HIDDEN" : "shown"}`
                worst = 0
            }, 500)
        }

        return () => {
            disposed = true
            if (dbgTimer) clearInterval(dbgTimer)
            if (dbgRaf) cancelAnimationFrame(dbgRaf)
            dbgEl?.remove()
            ctrl?.abort()
            for (const u of objectUrls) if (u) URL.revokeObjectURL(u)
            for (const w of workers) w.terminate()
            if (workerUrl) URL.revokeObjectURL(workerUrl)
            workerJobs.clear()
            if (raf) cancelAnimationFrame(raf)
            ro?.disconnect()
            window.removeEventListener("scroll", onScroll)
            if (coverTimer) clearTimeout(coverTimer)
            window.removeEventListener("resize", onResize)
            for (const [, b] of bitmaps) (b as any).close?.()
            bitmaps.clear()
        }
    }, [urls, sectionHeight, rangeVh, startDelay, decodeAhead, smoothing, isCanvas])

    if (isCanvas) {
        return (
            <div
                style={{
                    ...style,
                    background: urls[0] ? `center / cover no-repeat url(${urls[0]})` : "rgba(136,85,255,0.1)",
                    display: "flex",
                    alignItems: "flex-end",
                    justifyContent: "center",
                    color: "rgba(255,255,255,0.7)",
                    fontSize: 11,
                }}
            >
                {urls.length ? `${urls.length} frames` : "Paste frame URLs"}
            </div>
        )
    }
    return (
        <div ref={wrapRef} style={{ ...style, position: "relative", width: "100%", height: "100%", pointerEvents: "none" }}>
            <canvas
                ref={canvasRef}
                aria-hidden="true"
                style={{ position: "absolute", inset: 0, width: "100%", height: "100%", display: "block" }}
            />
        </div>
    )
}

addPropertyControls(NimbusSequencePlayer, {
    frames: { type: ControlType.String, title: "Frames", displayTextArea: true, defaultValue: "", placeholder: "Frame URLs, one per line, in order" },
    sectionHeight: { type: ControlType.Number, title: "Section Height", defaultValue: 1688, min: 100, step: 10 },
    rangeVh: {
        type: ControlType.Number,
        title: "Range (vh)",
        description: "Scroll distance of the whole animation in viewport heights. 0 = auto (sticky travel, else Section Height).",
        defaultValue: 0,
        min: 0,
        max: 1000,
        step: 10,
        unit: "vh",
    },
    startDelay: { type: ControlType.Number, title: "Start Delay", defaultValue: 0, min: 0, step: 10 },
    decodeAhead: { type: ControlType.Number, title: "Decode Ahead", defaultValue: 12, min: 2, max: 40, step: 1 },
    smoothing: { type: ControlType.Number, title: "Smoothing", defaultValue: 0.12, min: 0, max: 0.6, step: 0.01, unit: "s", description: "0 = theo sát scroll; lớn hơn = trôi mượt hơn" },
})
